 * Runs the instant-runoff count described by the specification and returns
 * one entry per round plus the eventual winner, or `null` when no candidate
 * ever reaches a majority.
 */

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  let winner = null

  for (;;) {
    const tally = new Map()
    for (const c of continuing) tally.set(c, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.candidates.find((c) => continuing.has(c))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(pick, tally.get(pick) + ballot.count)
      }
    }

    for (const c of continuing) history.get(c).push(tally.get(c))

    const activeTotal = sum([...tally.values()])
    const roundNumber = rounds.length + 1

    if (activeTotal === 0) {
      rounds.push({ tally, exhausted, eliminated: null })
      winner = null
      break
    }

    const majority = [...continuing].find((c) => tally.get(c) * 2 > activeTotal)
    if (majority !== undefined) {
      rounds.push({ tally, exhausted, eliminated: null })
      winner = majority
      break
    }

    const minVotes = Math.min(...[...continuing].map((c) => tally.get(c)))
    const tied = [...continuing].filter((c) => tally.get(c) === minVotes)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history, roundNumber)
    continuing.delete(eliminated)
    rounds.push({ tally, exhausted, eliminated })
  }

  return { rounds, winner }
}

function breakTie(tied, history, roundsSoFar) {
  let survivors = tied.slice()
  let changed = true
  while (changed && survivors.length > 1) {
    changed = false
    for (let r = 0; r < roundsSoFar; r++) {
      const counts = survivors.map((c) => history.get(c)[r])
      if (!counts.every((v) => v === counts[0])) {
        const min = Math.min(...counts)
        survivors = survivors.filter((c, i) => counts[i] === min)
        changed = true
        break
      }
    }
  }
  if (survivors.length === 1) return survivors[0]
  return survivors.slice().sort().pop()
}

function sum(values) {
  return values.reduce((a, b) => a + b, 0)
}
"}

