/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { runElection } from './election.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    throw new UsageError('usage: cli.js rounds|tally')
  }

  const text = await readStdin()
  const { candidates, ballots } = parseElection(text)
  const { rounds, winner } = runElection(candidates, ballots)

  const output = mode === 'rounds' ? formatRounds(rounds, winner) : formatTally(rounds, winner)
  process.stdout.write(output)
}

class UsageError extends Error {}

main().then(
  () => {
    process.exitCode = 0
  },
  (err) => {
    if (err instanceof UsageError) {
      process.stderr.write(`error: ${err.message}\n`)
    } else if (err.noLineNumber) {
      process.stderr.write(`error: ${err.message}\n`)
    } else {
      process.stderr.write(`error: ${err.message}\n`)
    }
    process.exitCode = 2
  },
)
"}

